// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }
    function testRegression_property() public {
        vm.prank(0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001);
        c.setL1BlockValues(5, 100, 1000, bytes32(uint256(0x1234)), 1, bytes32(uint256(0x5678)), 10, 20);
        assertEq(c.number(), 5);
    }
}
